package io.github.jerryperezperez.scrapingant4j;

import feign.Param;
import feign.QueryMap;
import feign.RequestLine;
import java.util.Map;

/** Internal Feign interface for ScrapingAnt API calls. */
interface ScrapingAntApi {

  /**
   * Sends a scrape request to the configured endpoint.
   *
   * @param queryParams parameters generated by {@code ScrapingAntRequest.toQueryMap()}.
   * @return the raw response body.
   */
  @RequestLine("GET /{extraction_type}")
  String scrape(
      @QueryMap Map<String, Object> queryParams,
      @Param("extraction_type") String extractionTypeValue);
}
